const $=id=>document.getElementById(id),storageKey='a7-studio-v1';let items=clone(initialFurniture),palette='oak',selected=null,history=[],future=[],beforeDrag=null,dragBlocked=false,placementCandidate=null,schemes=[],scene,noticeTimer;
