function renderList(){const q=$('search').value.toLowerCase();$('count').textContent=items.length+' 件家具';$('objects').replaceChildren();const list=[...items.map(f=>({id:f.id,name:f.name,sub:`${Math.round(f.w*100)} × ${Math.round(f.d*100)} × ${Math.round(f.h*100)} cm`,icon:icons[f.type],warn:issues(f,items).length>0})),...doors.map(d=>({id:d.id,name:d.name,sub:'固定位置 · 可開關',icon:'▯'})),...[0,1,2].map(i=>({id:'curtain-'+i,name:['客廳窗簾','臥室 A 窗簾','主臥窗簾'][i],sub:'固定位置 · 可開合',icon:'▥'}))];for(const f of list){if(!f.name.toLowerCase().includes(q))continue;let b=document.createElement('button');b.className='object'+(selected===f.id?' active':'');b.setAttribute('aria-pressed',selected===f.id);let icon=document.createElement('span');icon.className='icon';icon.textContent=f.icon;let text=document.createElement('span');text.textContent=f.name;let sub=document.createElement('small');sub.textContent=f.sub;text.append(sub);b.append(icon,text);if(f.warn){let dot=document.createElement('span');dot.className='dot';dot.textContent='!';dot.title='配置有待檢查';b.append(dot);}b.onclick=()=>select(f.id);$('objects').append(b);}}
