const context=document.modelContext;if(context?.registerTool){try{context.registerTool({name:'read_space_configuration',description:'Read the current A7 furniture configuration in metres.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()});context.registerTool({name:'update_furniture_dimensions',description:'Set an existing furniture item width, depth and height in centimetres, updating the visible model and local save.',inputSchema:{type:'object',properties:{id:{type:'string'},width:{type:'number',minimum:10,maximum:500},depth:{type:'number',minimum:10,maximum:500},height:{type:'number',minimum:1,maximum:279}},required:['id','width','depth','height'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const f=items.find(f=>f.id===input.id);if(!f)throw Error('Furniture not found');const n={...f,w:input.width/100,d:input.depth/100,h:input.height/100};validateFurniture([n]);commitFurniture(f,n);select(f.id);return{furniture:clone(f),warnings:issues(f,items)};}});}catch(e){console.warn('Optional model context unavailable',e)}}
render();updateUndo();persist();
